#![no_std]
#![no_main]
use k256::ecdsa::signature::hazmat::PrehashVerifier;
use k256::ecdsa::{Signature, VerifyingKey};

const PUB: [u8; 65] = [
    0x04, 0x35, 0x02, 0x62, 0x21, 0xe5, 0xba, 0x0b, 0x1c, 0x62, 0xe9, 0xa5, 0x12, 0x29, 0x04, 0x4b,
    0xb4, 0x8c, 0xd9, 0x59, 0xd8, 0xea, 0x71, 0x88, 0xa4, 0x33, 0xb6, 0x15, 0xd7, 0x15, 0x35, 0x65,
    0x99, 0x6c, 0x11, 0x9d, 0xac, 0x71, 0x98, 0xc9, 0x8c, 0x09, 0x77, 0xc6, 0xda, 0x5b, 0xb3, 0x0c,
    0xef, 0x02, 0xb5, 0x95, 0x91, 0x7c, 0x4e, 0xc8, 0xff, 0x3f, 0xde, 0xa7, 0xff, 0xbb, 0xf6, 0x9b,
    0x4c,
];
const DIGEST: [u8; 32] = [
    0xb4, 0x26, 0xf1, 0x71, 0x39, 0x5a, 0xb7, 0x14, 0x70, 0x34, 0xa3, 0x6a, 0x20, 0x30, 0x62,
    0x50, 0x96, 0xd9, 0xea, 0xb5, 0xe4, 0x2b, 0x13, 0x0c, 0x8f, 0x4a, 0x41, 0x1a, 0xb0, 0x10,
    0x1e, 0x6f,
];
const SIG: [u8; 64] = [
    0x8f, 0x89, 0xdf, 0x0e, 0x0e, 0x90, 0xa9, 0x0f, 0xeb, 0x42, 0x20, 0x0d, 0xf1, 0x83, 0xbf,
    0xbf, 0xac, 0x56, 0x63, 0xb6, 0x06, 0x37, 0xe1, 0xa5, 0x6e, 0x7d, 0x31, 0x6d, 0x7c, 0x28,
    0x7a, 0xf3, 0x1c, 0x30, 0x20, 0xd7, 0xca, 0xbe, 0xed, 0xaf, 0xdb, 0xe5, 0x2e, 0x5e, 0xd1,
    0xfd, 0x3f, 0xb6, 0x88, 0x4e, 0x27, 0x6c, 0xd7, 0xd6, 0xbd, 0xa1, 0xc2, 0x19, 0xfa, 0x49,
    0x94, 0xd1, 0xe1, 0x5c,
];

fn kernel(_input: &[u8], out: &mut [u8]) -> usize {
    let vk = VerifyingKey::from_sec1_bytes(&PUB).unwrap();
    let sig = Signature::from_slice(&SIG).unwrap();
    out[0] = if vk.verify_prehash(&DIGEST, &sig).is_ok() {
        1
    } else {
        0
    };
    1
}

include!("../boot.rs");
